def scope_programme_id(module_rows, scope='', identifier=''):
    """The programme a coverage request sits under, whatever it was scoped by."""
    if scope == 'programme' and clean_str(identifier):
        return clean_str(identifier)
    return clean_str(next((
        row.get('programme_id') for row in module_rows if clean_str(row.get('programme_id'))
    ), ''))

active_ksb_profiles.source:
def active_ksb_profiles(ksb_profiles):
    """The manual profiles still in use. ``is_active = false`` is how a profile is
    archived (2026-10-15_archive_manual_ksb_profiles); a row without the flag
    counts as active."""
    return [
        profile for profile in ksb_profiles or []
        if (profile or {}).get('is_active') is None or not falsey(profile.get('is_active'))
    ]

get_ksb_profile_for_program.source:
def get_ksb_profile_for_program(program_name, ksb_profiles):
    program_norm = normalise(program_name)
    if not program_norm:
        return None
    for profile in ksb_profiles:
        candidates = [
            profile.get('name'),
            *ksb_profile_context_ids(profile, 'programme_ids'),
        ]
        for candidate in candidates:
            candidate_norm = normalise(candidate)
            if candidate_norm == program_norm:
                return profile
    return None

programme_applied_ksb_profile.source:
def programme_applied_ksb_profile(config, ksb_profiles, *programme_names):
    """The manual KSB profile a programme applies, or None.

    The stored source decides (programme_config_ksb_source):

    - a standard: no manual profile speaks for the programme. Applying a standard
      never unlinks the programme from a profile's ``programme_ids``, so a
      profile still listing it -- archived or not -- is a leftover link. Reading
      it made a programme on ST0845 call itself "Empty KSB profile";
    - a profile: that profile, whatever its state, because the row chose it;
    - nothing: the legacy match by programme name, against active profiles only,
      so an archived profile cannot name a programme by accident.
    """
    source_type, source_id = programme_config_ksb_source(config)
    if source_type == 'standard':
        return None
    if source_id:
        wanted = normalise(source_id)
        for profile in ksb_profiles or []:
            profile_id = clean_str(profile.get('id'))
            identities = {
                profile_id,
                clean_str(profile.get('ksb_profile_id')),
                ksb_profile_source_id(profile),
                f'ksb-{profile_id}' if profile_id else '',
            }
            if wanted in {normalise(value) for value in identities if value}:
                return profile
        return None
    active = active_ksb_profiles(ksb_profiles)
    for name in programme_names:
        profile = get_ksb_profile_for_program(name, active)
        if profile:
            return profile
    return None

_skills_england_standard_index.source:
def _skills_england_standard_index():
    """``{identifier: standard}`` for every name a standard answers to; the
    first standard (in build order) keeps a shared identifier."""
    index = {}
    for standard in build_skills_england_standards():
        for candidate in (
            clean_str(standard.get('id')).lower(),
            clean_str(standard.get('code')).lower(),
            slugify(standard.get('name')).lower(),
            slugify(f'{standard.get("code")}-v{standard.get("version")}').lower(),
        ):
            index.setdefault(candidate, standard)
    return index

all_standard_required_ksbs.source:
def all_standard_required_ksbs():
    definitions = []
    seen = set()
    for standard in build_skills_england_standards():
        for definition in standard_required_ksb_definitions(standard, standard.get('id')):
            identity = (
                clean_str(definition.get('source_type')).lower(),
                clean_str(definition.get('source_id')).lower(),
                coverage_normalise_code(definition.get('code')),
            )
            if identity in seen:
                continue
            seen.add(identity)
            definitions.append(definition)
    return definitions

required_ksbs_for_source.source:
def required_ksbs_for_source(source_type='', source_id=''):
    source_type, source_id = split_ksb_source(source_type, source_id)
    if source_type == 'standard' and not source_id:
        return all_standard_required_ksbs()
    if source_type == 'standard' and source_id:
        return standard_required_ksbs(source_id)
    # 'framework'/'profile' sources were KSB profiles, which no longer exist.
    return []

source_required_ksbs.source:
def source_required_ksbs(source_type, source_id, cache=None):
    source_type, source_id = split_ksb_source(source_type, source_id)
    cache = cache if cache is not None else {}
    key = (source_type, source_id)
    if key not in cache:
        cache[key] = required_ksbs_for_source(source_type, source_id)
    return cache[key]

ksb_exists_in_source.source:
def ksb_exists_in_source(source_type, source_id, code, cache=None):
    source_type, source_id = split_ksb_source(source_type, source_id)
    if not source_type or not source_id:
        return False
    normalised = coverage_normalise_code(code)
    return any(coverage_normalise_code(item.get('code')) == normalised for item in source_required_ksbs(source_type, source_id, cache))

programme_row_ksb_source.source:
def programme_row_ksb_source(programme_id):
    """The KSB source stored on the programme row itself.

    `curriculum.programmes.ksb_profile_source_id` is what the Programme form
    writes and what `set_programme_modules_ksb_source` cascades onto every
    module underneath, so it is the authority for any scope inside that
    programme. Nothing on the coverage path used to read it: a programme whose
    name no longer matched an entry in a profile's `programme_ids` fell all the
    way through to the union of every profile without saying so.
    """
    ident = clean_str(programme_id)
    ident_key = normalise(ident)
    if not ident_key:
        return '', ''
    for row in get_program_config_rows():
        candidates = {
            normalise(programme_config_identity(row)),
            normalise(row.get('name')),
        }
        candidates.discard('')
        if ident_key not in candidates:
            continue
        return programme_config_ksb_source(row)
    return '', ''

infer_source_from_scope.source:
def infer_source_from_scope(module_rows, scope='', identifier=''):
    """Which KSB source this scope's required set comes from, and how it was
    arrived at. Most explicit first, so a stored source always beats a name that
    happens to match one."""
    stored_type, stored_id = programme_row_ksb_source(scope_programme_id(module_rows, scope, identifier))
    if stored_type and stored_id:
        return stored_type, stored_id, 'programme'
    explicit = next((
        (row.get('source_type'), row.get('source_id'))
        for row in module_rows
        if row.get('source_type') in {'standard', 'framework', 'profile'} and row.get('source_id')
    ), None)
    if explicit:
        return (*split_ksb_source(*explicit), 'module')
    # The copy the programme cascaded onto its modules, for a module whose
    # programme row has since lost (or never carried) the value.
    cascaded = next((
        normalise_ksb_profile_source_value(row.get('ksb_profile_source_id'))
        for row in module_rows
        if clean_str(row.get('ksb_profile_source_id'))
    ), '')
    if cascaded:
        return (*split_ksb_source('', cascaded), 'module')
    programme_name = clean_str((module_rows[0] if module_rows else {}).get('programme_name'))
    if not programme_name:
        return '', '', ''
    # Active profiles only, as the programme card's label reads them: an
    # archived profile still listing this name is a leftover link, not a source.
    profile = get_ksb_profile_for_program(programme_name, active_ksb_profiles(get_ksb_profile_rows()))
    if profile:
        return 'framework', f'ksb-{profile.get("id")}', 'programme-name'
    standard = next((item for item in build_skills_england_standards() if normalise(item.get('name')) == normalise(programme_name)), None)
    if standard:
        return 'standard', standard.get('id'), 'programme-name'
    return '', '', ''

required_ksbs_for_resolved_source.source:
def required_ksbs_for_resolved_source(source_type, source_id, origin):
    if origin == 'all-profiles':
        # No source on the scope: there are no KSB profiles to fall back on, so
        # coverage is mapping-only.
        return []
    return required_ksbs_for_source(source_type, source_id)

infer_mapping_source_from_module.source:
def infer_mapping_source_from_module(module, code, cache=None):
    module = module or {}
    cache = cache if cache is not None else {}
    clean_code = coverage_normalise_code(code)
    cache_key = (
        clean_str(module.get('module_catalogue_id')),
        clean_str(module.get('ksb_profile_source_id')),
        clean_str(module.get('programme_name')),
        clean_code,
    )
    if cache_key in cache:
        return cache[cache_key]
    source_cache = cache.setdefault('_source_required', {})
    explicit_type, explicit_id = split_ksb_source('', module.get('ksb_profile_source_id'))
    if explicit_type and explicit_id and ksb_exists_in_source(explicit_type, explicit_id, clean_code, source_cache):
        cache[cache_key] = (explicit_type, explicit_id)
        return cache[cache_key]

    programme_name = clean_str(module.get('programme_name'))
    if not programme_name:
        cache[cache_key] = ('', '')
        return cache[cache_key]

    if '_profile_rows' not in cache:
        cache['_profile_rows'] = get_ksb_profile_rows()
    profile_rows = cache['_profile_rows']
    profile = get_ksb_profile_for_program(programme_name, profile_rows)
    if profile:
        profile_source_id = f'ksb-{profile.get("id")}'
        if ksb_exists_in_source('framework', profile_source_id, clean_code, source_cache):
            cache[cache_key] = ('framework', profile_source_id)
            return cache[cache_key]

    if '_standards' not in cache:
        cache['_standards'] = build_skills_england_standards()
    standards = cache['_standards']
    standard = next((item for item in standards if normalise(item.get('name')) == normalise(programme_name)), None)
    if standard and ksb_exists_in_source('standard', standard.get('id'), clean_code, source_cache):
        cache[cache_key] = ('standard', standard.get('id'))
        return cache[cache_key]

    cache[cache_key] = ('', '')
    return cache[cache_key]

mappings_with_inferred_sources.source:
def mappings_with_inferred_sources(mapping_rows, module_rows):
    module_by_id = {clean_str(row.get('module_catalogue_id')): row for row in module_rows}
    # One cache for the whole batch, the way authoring_mapping_payload already
    # threads its `source_cache`. Passing nothing gave every row a fresh cache,
    # and each fresh cache re-read the KSB profiles and the Skills England
    # standards -- whole tables, no where clause -- to answer about one code. A
    # module with thirty unsourced mappings paid for that thirty times over.
    source_cache = {}
    enriched = []
    for row in mapping_rows:
        if clean_str(row.get('source_type')) and clean_str(row.get('source_id')):
            enriched.append(row)
            continue
        source_type, source_id = infer_mapping_source_from_module(
            module_by_id.get(clean_str(row.get('module_catalogue_id')), {}),
            row.get('ksb_code'),
            source_cache,
        )
        enriched.append({**row, 'source_type': source_type, 'source_id': source_id} if source_type and source_id else row)
    return enriched

source_display_metadata.source:
def source_display_metadata(source_type='', source_id=''):
    source_type, source_id = split_ksb_source(source_type, source_id)
    if source_type == 'standard' and source_id:
        standard = find_skills_england_standard(source_id)
        if standard:
            name = clean_str(standard.get('name')) or clean_str(standard.get('code')) or source_id
            ref = clean_str(standard.get('code'))
            version = clean_str(standard.get('version'))
            suffix = ' '.join(part for part in [ref, f'v{version}' if version else ''] if part)
            label = f'{name} ({suffix})' if suffix and suffix.lower() not in name.lower() else name
            return {
                'source_name': name,
                'sourceName': name,
                'source_label': label,
                'sourceLabel': label,
            }
    if source_type in {'framework', 'profile'} and source_id:
        ident = clean_str(source_id).replace('ksb-', '', 1)
        matched = next((
            row for row in get_ksb_profile_rows()
            if ident in {
                clean_str(row.get('id')),
                slugify(row.get('name') or ''),
                *ksb_profile_context_ids(row, 'programme_ids'),
            } or ident in {slugify(value) for value in ksb_profile_context_ids(row, 'programme_ids')}
        ), None)
        if matched:
            name = clean_str(matched.get('name')) or source_id
            label = name
            return {
                'source_name': name,
                'sourceName': name,
                'source_label': label,
                'sourceLabel': label,
            }
    fallback_type = source_type_label(source_type) if source_type else ''
    fallback = f'{fallback_type}: {source_id}' if fallback_type and source_id else ''
    return {
        'source_name': fallback,
        'sourceName': fallback,
        'source_label': fallback,
        'sourceLabel': fallback,
    }

annotate_coverage_sources.source:
def annotate_coverage_sources(coverage):
    cache = {}

    def apply_metadata(item):
        if not isinstance(item, dict):
            return item
        source_type = item.get('source_type') or item.get('sourceType')
        source_id = item.get('source_id') or item.get('sourceId')
        key = (clean_str(source_type), clean_str(source_id))
        if key not in cache:
            cache[key] = source_display_metadata(source_type, source_id)
        item.update(cache[key])
        return item

    for item in coverage.get('items') or []:
        apply_metadata(item)
        for mapping in item.get('mappings') or []:
            apply_metadata(mapping)
    for row in (coverage.get('heatmap') or {}).get('rows') or []:
        apply_metadata(row)
        for module in row.get('modules') or []:
            for mapping in module.get('mappings') or []:
                apply_metadata(mapping)
    return coverage

programme_component_ksb_mapping_count.source:
def programme_component_ksb_mapping_count(programme_id, required_codes=None):
    """Distinct required KSBs actually mapped to this programme's components."""
    required = {coverage_normalise_code(code) for code in (required_codes or []) if coverage_normalise_code(code)}
    try:
        return programme_ksb_design_value(
            'mapped', programme_id,
            lambda: _programme_component_ksb_mapping_count(programme_id, required),
            extra_key=hashlib.sha256(json.dumps(sorted(required)).encode()).hexdigest()[:16],
        )
    except _ProgrammeKsbDesignUnavailable as failure:
        logger.warning('Could not count programme component KSB mappings for %s: %s', programme_id, failure.exc)
        return 0

_programme_component_ksb_mapping_count.source:
def _programme_component_ksb_mapping_count(programme_id, required):
    try:
        module_rows, _week_rows, _component_rows, mapping_rows = authoring_scope_data('programme', programme_id, stats_only=True)
    except Exception as exc:
        raise _ProgrammeKsbDesignUnavailable('scope', exc) from exc
    module_ids = {clean_str(row.get('module_catalogue_id')) for row in module_rows if clean_str(row.get('module_catalogue_id'))}
    mapped = set()
    for row in mapping_rows:
        if clean_str(row.get('module_catalogue_id')) not in module_ids:
            continue
        if not clean_str(row.get('component_id')):
            continue
        code = coverage_normalise_code(row.get('ksb_code'))
        if not code:
            continue
        matched_code = code
        if required and matched_code not in required:
            parent_code = code.split('.', 1)[0]
            if parent_code in required:
                matched_code = parent_code
            else:
                continue
        mapped.add(matched_code)
    return len(mapped)

_programme_ksb_expected_weights.source:
def _programme_ksb_expected_weights(programme_id):
    """The design side of programme_learner_ksb_progress: mapped weight per KSB.

    ``{}`` when there is nothing to measure (no modules, nothing mapped); raises
    _ProgrammeKsbDesignUnavailable when a read fails, so a failure is never
    cached as an empty design.
    """
    try:
        module_rows, week_rows, component_rows, mapping_rows = authoring_scope_data('programme', programme_id, stats_only=True)
    except Exception as exc:
        raise _ProgrammeKsbDesignUnavailable('scope', exc) from exc
    if not module_rows:
        return {}
    try:
        mapping_rows = mappings_with_inferred_sources(mapping_rows, module_rows)
        required_ksbs = required_ksbs_for_resolved_source(*infer_source_from_scope(module_rows, 'programme', programme_id))
        coverage = build_coverage(
            required_ksbs,
            mapping_rows,
            module_rows,
            week_rows,
            component_rows,
            include_mapping_only=not bool(required_ksbs),
            totals_only=True,
        )
    except Exception as exc:
        raise _ProgrammeKsbDesignUnavailable('coverage', exc) from exc

    # Denominator: mapped weight per KSB. A code the design never mapped carries
    # no expected weight, so it cannot drag the percentage down.
    expected = {}
    for item in coverage.get('items', []):
        code = coverage_normalise_code(item.get('code'))
        if not code:
            continue
        weight = float(item.get('raw_total_weight') or item.get('rawTotalWeight') or 0)
        if weight > 0:
            expected[code] = expected.get(code, 0.0) + weight
    return expected

curriculum_programme_ksb_stats.source:
def curriculum_programme_ksb_stats(request, programme_id):
    visibility = curriculum_visibility(request)
    identifier = clean_str(programme_id)
    force = request_bypasses_curriculum_cache(request)
    def build_entry():
        with forced_programme_ksb_design(force):
            stats = build_programme_ksb_stats(identifier, visibility)
        if not stats:
            return encode_json_error_entry('Programme not found.', status=404)
        return encode_json_entry(stats)

    entry = cached_curriculum_value(
        f'programme-ksb-stats-response:{visibility}:{identifier}',
        build_entry,
        force=force,
        ttl=CURRICULUM_LEARNER_DATA_TTL_SECONDS,
        scope=identifier,
    )
    return conditional_json_response(request, entry)
